using Avalonia.Controls;using Avalonia.Layout;using Avalonia.Media;using SPharmacyLog.Core;namespace SPharmacyLog.UI.Views;public sealed class LoginWindow:Window{PharmacyAuthService auth=new();TextBox user=new(){PlaceholderText="Username",Width=300};TextBox pass=new(){PlaceholderText="Password (minimum 8 characters)",PasswordChar='•',Width=300};TextBlock message=new(){TextWrapping=TextWrapping.Wrap,Foreground=Brushes.OrangeRed};Button submit=new(){Content="Sign in",Width=300};bool first;public LoginWindow(){Title="S Pharmacy Log";Width=440;Height=500;CanResize=false;WindowStartupLocation=WindowStartupLocation.CenterScreen;Content=new StackPanel{Spacing=12,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center,Children={new TextBlock{Text="S Pharmacy Log",FontSize=28,FontWeight=FontWeight.Bold,HorizontalAlignment=HorizontalAlignment.Center},new TextBlock{Text="Prescription, customer and medicine tracking",Foreground=Brushes.Gray},user,pass,message,submit}};submit.Click+=async(_,_)=>await Submit();Opened+=async(_,_)=>await Setup();}async Task Setup(){first=!await auth.HasUsersAsync();submit.Content=first?"Create first administrator":"Sign in";message.Text=first?"First launch: create admin (password min. 8 characters).":"";}async Task Submit(){submit.IsEnabled=false;try{if(first){await auth.CreateFirstAdminAsync(user.Text??"",pass.Text??"");message.Text="Administrator created; please sign in.";pass.Text="";await Setup();return;}var u=await auth.LoginAsync(user.Text??"",pass.Text??"");if(u==null){message.Text="Login failed. Check credentials or user active status.";return;}new MainWindow(u).Show();Close();}catch(Exception e){message.Text=e.Message;}finally{submit.IsEnabled=true;}}}